#include <linux/uaccess.h>
#include <linux/net.h>
#include <linux/socket.h>

int handle_siocgstampns_ioctl(struct net *net, struct socket *sock, unsigned int cmd, void __user *up)
{
    int ret;
    mm_segment_t old_fs = get_fs();
    struct timespec ts;

    set_fs(KERNEL_DS);
    ret = sock_do_ioctl(net, sock, cmd, (unsigned long)&ts);
    set_fs(old_fs);

    if (ret < 0)
        return ret;

    ret = compat_put_timespec(&ts, up);
    return ret;
}

